-- Disposable LOCAL only. Opt-in: SET nova.security_test='isolated'. All rows roll back.
\set ON_ERROR_STOP on
BEGIN;
DO $$ BEGIN IF current_user<>'postgres' OR current_setting('nova.security_test',true) IS DISTINCT FROM 'isolated' THEN RAISE EXCEPTION 'LOCAL isolated opt-in required'; END IF; END; $$;
CREATE FUNCTION pg_temp.check_order(ok boolean,label text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'FAIL: %',label; END IF; RAISE NOTICE 'PASS: %',label; END; $$;
DO $$
DECLARE a uuid:=gen_random_uuid(); e uuid:=gen_random_uuid(); inactive uuid:=gen_random_uuid(); m uuid:=gen_random_uuid(); p uuid:=gen_random_uuid(); opt uuid:=gen_random_uuid();
 o uuid; pay uuid; item uuid; snapshot jsonb; fail boolean; stamp timestamptz:=((current_timestamp AT TIME ZONE 'America/La_Paz')::date+1+time '10:30') AT TIME ZONE 'America/La_Paz';
 original_stock numeric; before_lots numeric; cash uuid;
BEGIN
 INSERT INTO auth.users(id,email) VALUES(a,a||'@example.invalid'),(e,e||'@example.invalid'),(inactive,inactive||'@example.invalid');
 UPDATE profiles SET role=CASE WHEN id=a THEN 'administrador' ELSE 'empleado' END,is_active=id<>inactive WHERE id IN(a,e,inactive);
 PERFORM set_config('request.jwt.claim.sub',a::text,true);
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true);
 UPDATE business_hours SET is_closed=false,opens_at='08:00',closes_at='20:00';
 UPDATE system_settings SET value='{"enabled":true}' WHERE key='accept_orders_outside_hours';
 INSERT INTO inventory_items(id,name,item_type,unit) VALUES(m,'Material sintético de auditoría de pedidos','insumo','unidad');
 INSERT INTO inventory_entries(inventory_item_id,quantity,created_by,received_at) VALUES(m,50,a,now()-interval '2 days'),(m,50,a,now()-interval '1 day');
 INSERT INTO products(id,name,price) VALUES(p,'Arreglo sintético de auditoría de pedidos',100);
 INSERT INTO product_inventory_requirements(product_id,inventory_item_id,quantity) VALUES(p,m,2);
 UPDATE products SET is_active=true,is_available=true WHERE id=p;
 INSERT INTO customization_options(id,product_id,option_type,name,extra_price)VALUES(opt,p,'otro','Presentación adicional',5);
 INSERT INTO customization_option_inventory_requirements(customization_option_id,inventory_item_id,quantity)VALUES(opt,m,1);
 SELECT current_stock INTO original_stock FROM inventory_items WHERE id=m;
 o:=create_order('Cliente sintético de auditoría','70000404',NULL,jsonb_build_array(jsonb_build_object('product_id',p,'quantity',1,'customization_option_ids',jsonb_build_array(opt))), 'Método: Retiro en tienda','audit-order-schedule-'||a,NULL);
 SELECT id,recipe_snapshot INTO item,snapshot FROM order_items WHERE order_id=o;
 PERFORM pg_temp.check_order((snapshot->>'version')::integer=1 AND (snapshot->'materials'->0->>'quantity_per_unit')::numeric=3,'future recipe snapshot includes customization per unit');
 PERFORM pg_temp.check_order(set_order_schedule(o,stamp,'proposed',0,false)=1,'proposed schedule persisted');
 PERFORM pg_temp.check_order((SELECT schedule_status='proposed' AND NOT schedule_client_confirmed AND schedule_updated_by=a FROM orders WHERE id=o),'proposal does not claim client acceptance; actor saved');
 fail:=false;BEGIN PERFORM set_order_schedule(o,stamp,'confirmed',1,false);EXCEPTION WHEN raise_exception THEN fail:=true;END;
 PERFORM pg_temp.check_order(fail,'confirmation needs explicit manual acknowledgement');
 PERFORM set_config('request.jwt.claim.sub',e::text,true);
 PERFORM set_order_schedule(o,stamp+interval '1 hour','confirmed',1,true);
 PERFORM pg_temp.check_order((SELECT schedule_revision=2 AND schedule_updated_by=e AND schedule_status='confirmed' FROM orders WHERE id=o),'active employee can coordinate and update schedule');
 fail:=false;BEGIN PERFORM set_order_schedule(o,stamp,'proposed',1,false);EXCEPTION WHEN serialization_failure THEN fail:=true;END;
 PERFORM pg_temp.check_order(fail,'stale concurrent revision rejected');
 fail:=false;BEGIN PERFORM set_order_schedule(o,now()-interval '1 day','proposed',2,false);EXCEPTION WHEN raise_exception THEN fail:=true;END;
 PERFORM pg_temp.check_order(fail,'past schedule rejected');
 fail:=false;BEGIN PERFORM set_order_schedule(o,now()+interval '181 days','proposed',2,false);EXCEPTION WHEN raise_exception THEN fail:=true;END;
 PERFORM pg_temp.check_order(fail,'unreasonable future horizon rejected');
 fail:=false;BEGIN PERFORM set_order_schedule(o,stamp+interval '12 hours','proposed',2,false);EXCEPTION WHEN raise_exception THEN fail:=true;END;
 PERFORM pg_temp.check_order(fail,'outside business hours rejected');
 UPDATE business_hours SET is_closed=true WHERE day_of_week=extract(dow FROM stamp AT TIME ZONE 'America/La_Paz');
 fail:=false;BEGIN PERFORM set_order_schedule(o,stamp,'proposed',2,false);EXCEPTION WHEN raise_exception THEN fail:=true;END;
 PERFORM pg_temp.check_order(fail,'closed day rejected');
 UPDATE business_hours SET is_closed=false;
 PERFORM set_config('request.jwt.claim.sub',inactive::text,true);
 fail:=false;BEGIN PERFORM set_order_schedule(o,stamp,'proposed',2,false);EXCEPTION WHEN insufficient_privilege THEN fail:=true;END;
 PERFORM pg_temp.check_order(fail,'inactive employee denied');
 PERFORM set_config('request.jwt.claim.sub','',true);PERFORM set_config('request.jwt.claims','{}',true);
 fail:=false;BEGIN PERFORM set_order_schedule(o,stamp,'proposed',2,false);EXCEPTION WHEN insufficient_privilege THEN fail:=true;END;
 PERFORM pg_temp.check_order(fail,'anonymous identity denied internally');
 PERFORM set_config('request.jwt.claim.sub',a::text,true);PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true);
 fail:=false;BEGIN UPDATE order_items SET recipe_snapshot='{}' WHERE id=item;EXCEPTION WHEN raise_exception THEN fail:=true;END;
 PERFORM pg_temp.check_order(fail,'historical snapshot immutable');
 SELECT id INTO pay FROM create_payment(o,'70000404');
 PERFORM pg_temp.check_order((SELECT current_stock=original_stock FROM inventory_items WHERE id=m),'schedule and report do not consume inventory');
 PERFORM confirm_payment(pay);PERFORM advance_order_status(o,'en_preparacion');PERFORM advance_order_status(o,'listo');PERFORM advance_order_status(o,'finalizado');
 PERFORM pg_temp.check_order((SELECT status='finalizado' FROM orders WHERE id=o),'confirmed pickup completes separate operational stages');
 PERFORM pg_temp.check_order((SELECT current_stock=original_stock-3 FROM inventory_items WHERE id=m),'confirmed stock consumed once');
 PERFORM pg_temp.check_order((SELECT remaining_quantity=47 FROM inventory_lots WHERE inventory_item_id=m ORDER BY received_at,id LIMIT 1),'FIFO old lot consumed');
 UPDATE product_inventory_requirements SET quantity=5 WHERE product_id=p AND inventory_item_id=m;
 PERFORM pg_temp.check_order((SELECT recipe_snapshot=snapshot FROM order_items WHERE id=item),'later recipe edit does not rewrite historical composition');
 fail:=false;BEGIN PERFORM set_order_schedule(o,stamp,'proposed',2,false);EXCEPTION WHEN raise_exception THEN fail:=true;END;
 PERFORM pg_temp.check_order(fail,'finalized order cannot be rescheduled');
 PERFORM pg_temp.check_order(EXISTS(SELECT 1 FROM audit_logs WHERE table_name='orders' AND record_id=o AND "after"->>'schedule_status'='confirmed' AND user_id=e),'existing audit records actual schedule actor and confirmation');
 PERFORM pg_temp.check_order((track_order_details('70000404',NULL,o)->>'receipt_token') IS NOT NULL,'public tracking confirmed receipt preserved');
 o:=create_order('Entrega sintética','70000405',NULL,jsonb_build_array(jsonb_build_object('product_id',p,'quantity',1)),'Método: Entrega por coordinar','audit-delivery-'||a,NULL);
 SELECT id INTO pay FROM create_payment(o,'70000405');PERFORM confirm_payment(pay);PERFORM advance_order_status(o,'en_preparacion');PERFORM advance_order_status(o,'listo');PERFORM advance_order_status(o,'finalizado');
 PERFORM pg_temp.check_order((SELECT status='finalizado' FROM orders WHERE id=o),'delivery completes without invented en-camino state');
 o:=create_order('Rechazo sintético','70000406',NULL,jsonb_build_array(jsonb_build_object('product_id',p,'quantity',1)),NULL,'audit-rejection-'||a,NULL);
 SELECT id INTO pay FROM create_payment(o,'70000406');PERFORM reject_payment(pay,'Rechazo sintético de auditoría');
 PERFORM pg_temp.check_order((SELECT status='rechazado' FROM orders WHERE id=o),'manual rejection preserved');
 o:=create_order('Cancelación sintética','70000407',NULL,jsonb_build_array(jsonb_build_object('product_id',p,'quantity',1)),NULL,'audit-cancel-'||a,NULL);
 PERFORM cancel_order(o,'Cancelación sintética de auditoría');
 PERFORM pg_temp.check_order((SELECT status='cancelado' FROM orders WHERE id=o),'cancellation with reason preserved');
 SELECT id INTO cash FROM cash_registers WHERE is_active ORDER BY id LIMIT 1;
 PERFORM open_cash_session(cash,0);
 SELECT sale.id INTO o FROM create_physical_sale(jsonb_build_array(jsonb_build_object('product_id',p,'quantity',1)),NULL,NULL,NULL,NULL,'efectivo') sale;
 PERFORM pg_temp.check_order((SELECT order_type='fisica' AND status='finalizado' FROM orders WHERE id=o),'physical sale remains finalized');
 PERFORM pg_temp.check_order((SELECT recipe_snapshot IS NOT NULL FROM order_items WHERE order_id=o),'physical sale snapshot captured');
 fail:=false;BEGIN PERFORM set_order_schedule(o,stamp,'proposed',0,false);EXCEPTION WHEN raise_exception THEN fail:=true;END;
 PERFORM pg_temp.check_order(fail,'physical sale scheduling denied');
 PERFORM pg_temp.check_order(NOT has_function_privilege('anon','public.set_order_schedule(uuid,timestamptz,text,integer,boolean)','EXECUTE'),'anon schedule RPC ACL denied');
 PERFORM pg_temp.check_order(NOT has_function_privilege('authenticated','public.capture_order_item_recipe()','EXECUTE'),'capture helper not directly callable by clients');
END; $$;
ROLLBACK;
